            if screen_result.pii.ipa:
                flagged_terms.extend([ip.text for ip in screen_result.pii.ipa])

        return ModerationResult(
            original_text=text_to_check,
            is_safe=is_safe,
            flagged_terms=list(set(flagged_terms))
        )
